From 565f7fe727464722b5d7281508b750fd13efdba4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:47:17 +0100
Subject: [PATCH] applet: show available VPN connections in their own section

VPN and WireGuard connections were mixed into the Available section
together with Wi-Fi and wired networks, sorted among them. They are now
listed after the other networks under their own VPN section header.

BUG: 435475
---
 libs/models/appletproxymodel.cpp | 27 +++++++++++++++++++++++++++
 libs/models/appletproxymodel.h   |  2 ++
 2 files changed, 29 insertions(+)

diff --git a/libs/models/appletproxymodel.cpp b/libs/models/appletproxymodel.cpp
index eceab62c3..4ea6f2644 100644
--- a/libs/models/appletproxymodel.cpp
+++ b/libs/models/appletproxymodel.cpp
@@ -11,6 +11,13 @@

 #include "configuration.h"

+#include <KLocalizedString>
+
+static bool isVpnType(NetworkManager::ConnectionSettings::ConnectionType type)
+{
+    return type == NetworkManager::ConnectionSettings::Vpn || type == NetworkManager::ConnectionSettings::WireGuard;
+}
+
 AppletProxyModel::AppletProxyModel(QObject *parent)
     : QSortFilterProxyModel(parent)
 {
@@ -24,6 +31,20 @@ AppletProxyModel::AppletProxyModel(QObject *parent)

 AppletProxyModel::~AppletProxyModel() = default;

+QVariant AppletProxyModel::data(const QModelIndex &index, int role) const
+{
+    if (role == NetworkModel::SectionRole) {
+        const QModelIndex sourceIndex = mapToSource(index);
+        const auto type = (NetworkManager::ConnectionSettings::ConnectionType)sourceModel()->data(sourceIndex, NetworkModel::TypeRole).toUInt();
+        const auto state = sourceModel()->data(sourceIndex, NetworkModel::ConnectionStateRole).toUInt();
+        if (isVpnType(type) && state == NetworkManager::ActiveConnection::Deactivated) {
+            return i18nc("@title:column header for list of available VPN connections", "VPN");
+        }
+    }
+
+    return QSortFilterProxyModel::data(index, role);
+}
+
 bool AppletProxyModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
 {
     const QModelIndex index = sourceModel()->index(source_row, 0, source_parent);
@@ -93,6 +114,12 @@ bool AppletProxyModel::lessThan(const QModelIndex &left, const QModelIndex &righ
         return false;
     }

+    const bool leftVpn = isVpnType((NetworkManager::ConnectionSettings::ConnectionType)sourceModel()->data(left, NetworkModel::TypeRole).toUInt());
+    const bool rightVpn = isVpnType((NetworkManager::ConnectionSettings::ConnectionType)sourceModel()->data(right, NetworkModel::TypeRole).toUInt());
+    if (leftVpn != rightVpn) {
+        return leftVpn;
+    }
+
     if (leftUuid.isEmpty() && !rightUuid.isEmpty()) {
         return true;
     } else if (!leftUuid.isEmpty() && rightUuid.isEmpty()) {
diff --git a/libs/models/appletproxymodel.h b/libs/models/appletproxymodel.h
index ba1a99ba6..63cc47e49 100644
--- a/libs/models/appletproxymodel.h
+++ b/libs/models/appletproxymodel.h
@@ -22,6 +22,8 @@ public:
     explicit AppletProxyModel(QObject *parent = nullptr);
     ~AppletProxyModel() override;

+    QVariant data(const QModelIndex &index, int role) const override;
+
 protected:
     bool filterAcceptsRow(int source_row, const QModelIndex &source_parent) const override;
     bool lessThan(const QModelIndex &left, const QModelIndex &right) const override;
-- 
